const themeButton=document.querySelector('.theme-toggle');function updateThemeButton(){const dark=document.documentElement.dataset.theme==='dark';themeButton.setAttribute('aria-label',`Switch to ${dark?'light':'dark'} theme`);themeButton.textContent=dark?'☀':'◐';}updateThemeButton();themeButton.addEventListener('click',()=>{document.documentElement.dataset.theme=document.documentElement.dataset.theme==='dark'?'light':'dark';try{localStorage.setItem('theme',document.documentElement.dataset.theme)}catch(e){}updateThemeButton()});
const filters=document.querySelectorAll('[data-filter]');filters.forEach(button=>button.addEventListener('click',()=>{filters.forEach(b=>b.setAttribute('aria-pressed',String(b===button)));let count=0;document.querySelectorAll('[data-category]').forEach(card=>{card.hidden=button.dataset.filter!=='all'&&card.dataset.category!==button.dataset.filter;if(!card.hidden)count++});document.querySelector('#project-count').textContent=button.dataset.filter==='all'?`Showing all ${count} projects`:`Showing ${count} ${button.dataset.filter.toLowerCase()} projects`;}));
const dialog=document.querySelector('.lightbox');
if(dialog){
 const image=dialog.querySelector('.viewer-stage img'),stage=dialog.querySelector('.viewer-stage'),caption=dialog.querySelector('.viewer-caption'),count=dialog.querySelector('.viewer-count'),prev=dialog.querySelector('.viewer-prev'),next=dialog.querySelector('.viewer-next'),minus=dialog.querySelector('.viewer-zoom-out'),plus=dialog.querySelector('.viewer-zoom-in'),fit=dialog.querySelector('.viewer-fit'),download=dialog.querySelector('.viewer-document');
 let opener,slides=[],index=0,scale=1,oldOverflow='',drag;
 const resize=()=>{if(!image.naturalWidth||!dialog.open)return;const ratio=Math.min((stage.clientWidth-12)/image.naturalWidth,(stage.clientHeight-12)/image.naturalHeight,1);image.style.width=Math.round(image.naturalWidth*ratio*scale)+'px';image.style.height=Math.round(image.naturalHeight*ratio*scale)+'px';stage.classList.toggle('is-zoomed',scale>1);minus.disabled=scale<=1;plus.disabled=scale>=5;fit.textContent=scale===1?'Fit':Math.round(scale*100)+'%'};
 const zoom=amount=>{scale=Math.max(1,Math.min(5,scale+amount));resize()};
 const show=()=>{const link=slides[index],thumb=link.querySelector('img');scale=1;image.style.width='';image.style.height='';image.alt=thumb?.alt||'Project image';caption.textContent=thumb?.alt||'';count.textContent=slides.length>1?`${index+1} / ${slides.length}`:'';prev.hidden=next.hidden=slides.length<2;prev.disabled=index===0;next.disabled=index===slides.length-1;download.hidden=!link.dataset.document;if(link.dataset.document)download.href=link.dataset.document;else download.removeAttribute('href');image.onload=resize;image.src=link.href;stage.scrollTop=stage.scrollLeft=0;if(image.complete)resize()};
 const move=delta=>{const target=index+delta;if(target<0||target>=slides.length)return;index=target;show()};
 document.querySelectorAll('.zoom-image').forEach(link=>link.addEventListener('click',event=>{if(!dialog.showModal)return;event.preventDefault();opener=link;const gallery=link.closest('[data-gallery]');slides=gallery?Array.from(gallery.querySelectorAll('.zoom-image')):[link];index=slides.indexOf(link);oldOverflow=document.body.style.overflow;dialog.showModal();show();document.body.style.overflow='hidden';dialog.querySelector('.close-viewer').focus()}));
 prev.addEventListener('click',()=>move(-1));next.addEventListener('click',()=>move(1));minus.addEventListener('click',()=>zoom(-0.5));plus.addEventListener('click',()=>zoom(0.5));fit.addEventListener('click',()=>{scale=1;resize();stage.scrollTop=stage.scrollLeft=0});
 dialog.addEventListener('keydown',event=>{if(event.ctrlKey||event.metaKey||event.altKey)return;if(event.key==='ArrowLeft'){event.preventDefault();move(-1)}if(event.key==='ArrowRight'){event.preventDefault();move(1)}if(event.key==='+'||event.key==='='){event.preventDefault();zoom(0.5)}if(event.key==='-'){event.preventDefault();zoom(-0.5)}});
 dialog.querySelector('.close-viewer').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',event=>{if(event.target===dialog){const rect=dialog.getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)dialog.close()}});dialog.addEventListener('close',()=>{document.body.style.overflow=oldOverflow;image.removeAttribute('src');opener?.focus()});window.addEventListener('resize',resize);
 stage.addEventListener('pointerdown',event=>{if(scale<=1||event.button!==0)return;drag={x:event.clientX,y:event.clientY,left:stage.scrollLeft,top:stage.scrollTop};stage.setPointerCapture(event.pointerId);stage.classList.add('is-dragging');event.preventDefault()});stage.addEventListener('pointermove',event=>{if(!drag)return;stage.scrollLeft=drag.left-(event.clientX-drag.x);stage.scrollTop=drag.top-(event.clientY-drag.y)});const endDrag=()=>{drag=null;stage.classList.remove('is-dragging')};stage.addEventListener('pointerup',endDrag);stage.addEventListener('pointercancel',endDrag);
}

if(typeof window!=='undefined'){
 const hero=document.querySelector('[data-home-video]'),heroButton=document.querySelector('.hero-playback');if(hero&&heroButton){const sync=()=>heroButton.textContent=hero.paused?'Play video':'Pause video';heroButton.addEventListener('click',()=>{if(hero.paused)hero.play().catch(sync);else hero.pause()});hero.addEventListener('play',sync);hero.addEventListener('pause',sync);const motion=matchMedia('(prefers-reduced-motion: reduce)');if(!motion.matches){hero.autoplay=true;hero.play().catch(sync)}motion.addEventListener('change',e=>{if(e.matches)hero.pause()});}
 document.querySelectorAll('video[controls]').forEach(v=>v.addEventListener('play',()=>{document.querySelectorAll('video[controls]').forEach(other=>{if(other!==v)other.pause()})}));
 document.querySelectorAll('[data-gallery]').forEach(g=>{const track=g.querySelector('.gallery-track'),slides=[...track.querySelectorAll('figure')],prev=g.querySelector('[data-prev]'),next=g.querySelector('[data-next]'),count=g.querySelector('[data-count]');if(!prev||!next)return;const position=()=>Math.round(track.scrollLeft/Math.max(1,track.clientWidth));const update=()=>{const index=position();count.textContent=`${index+1}/${slides.length}`;prev.disabled=index===0;next.disabled=index===slides.length-1};const move=d=>track.scrollTo({left:Math.max(0,Math.min(slides.length-1,position()+d))*track.clientWidth,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});prev.addEventListener('click',()=>move(-1));next.addEventListener('click',()=>move(1));track.addEventListener('scroll',update);update();});
}
